//! What a keystroke costs the language server, counted in files rather than
//! timed.
//!
//! A keystroke's cost is the analysis of the open document plus every entry
//! point its refresh queued, settled until nothing waits: queued work is
//! deferred work, and a count that left it out would pass while the editor
//! still did it all. [`keystroke`] is that whole cost, read off
//! [`SymbolIndex::take_work`].
//!
//! The tree is generated by [`tree`] rather than kept under `tests/lsp/`,
//! because its only property is its shape, and a fixture nobody reads rots
//! (the reason `tests/latency.rs` gives). It is many programs that each
//! autoload one shared library, which is the shape where a keystroke in a
//! library file has the most readers.
//!
//! Two of these tests name what a later stage of the incremental index makes
//! true, and fail with the counts they find until then: a body-only keystroke
//! in a library file parses one file and checks one file's bodies, whatever
//! the number of programs.

use std::fs;
use std::path::{Path, PathBuf};

use nvs_lsp::{CheckScope, Documents, SymbolIndex, Work, surface, uri_of};

/// A scratch directory that cleans up after itself.
struct TempDir {
    path: nvs_repo::Scratch,
}

impl TempDir {
    fn new(name: &str) -> Self {
        Self {
            path: nvs_repo::scratch(&format!("lsp-incremental-{name}")),
        }
    }

    fn write(&self, name: &str, text: &str) {
        let path = self.path.join(name);
        fs::create_dir_all(path.parent().expect("a fixture sits in a directory"))
            .expect("a scratch directory");
        fs::write(path, text).expect("a writable scratch file");
    }

    fn at(&self, name: &str) -> PathBuf {
        self.path.join(name)
    }

    fn root(&self) -> &Path {
        self.path.path()
    }
}

/// The name of the `n`th program: `Blog`, `Shop`, then `App3`, `App4` and on.
fn program(n: usize) -> String {
    match n {
        0 => "Blog".to_owned(),
        1 => "Shop".to_owned(),
        _ => format!("App{}", n + 1),
    }
}

/// The path of library class `n`, relative to the root.
fn part(n: usize) -> String {
    format!("lib/Framework/Part{n}.nvs")
}

/// Library class `n` of `library`. Each calls the next one's method, so a
/// program that uses one reaches them all. `Part0` and `Part1` declare a route
/// each, `Part2` a command, and `Part3` links to `Part0`'s route, so the
/// routes, commands and links tables have rows in more than one file.
fn library_class(n: usize, library: usize) -> String {
    let next = (n + 1) % library;
    let extra = match n {
        0 => "\n    #[Core\\Route(path: '/parts/{id}', method: Core\\Http\\Method::Get)]\n    \
              #[Core\\Access(allow: Core\\Audience::Public)]\n    \
              public function show(uint $id): string\n    {\n        return 'one part';\n    }\n"
            .to_owned(),
        1 => "\n    #[Core\\Route(path: '/parts', method: Core\\Http\\Method::Get)]\n    \
              #[Core\\Access(allow: Core\\Audience::Public)]\n    \
              public function list(): string\n    {\n        return 'every part';\n    }\n"
            .to_owned(),
        2 => "\n    #[Core\\Command(name: 'parts', about: 'List the parts')]\n    \
              public static function parts(): uint\n    {\n        return 0;\n    }\n"
            .to_owned(),
        3 => "\n    public function link(): string\n    {\n        \
              return Core\\Router::url(Part0::show, ['id' => 7]);\n    }\n"
            .to_owned(),
        _ => String::new(),
    };
    format!(
        "<?nvs\nnamespace Framework;\n\nclass Part{n}\n{{\n    \
         public function value(int $n): int\n    {{\n        return $n + {n};\n    }}\n\n    \
         public function next(int $n): int\n    {{\n        Part{next} $other = new Part{next}();\n        \
         return $other->value($n) + 1;\n    }}\n{extra}}}\n"
    )
}

/// Writes `programs` programs that each autoload the one library of `library`
/// classes under `lib/Framework/`. Each program has a `main.nvs` and two files
/// under `src/` that call into the library.
fn tree(programs: usize, library: usize) -> TempDir {
    assert!(
        library >= 4,
        "the library's routes, command and link need four classes"
    );
    let dir = TempDir::new(&format!("{programs}-{library}"));
    for n in 0..library {
        dir.write(&part(n), &library_class(n, library));
    }
    for p in 0..programs {
        let name = program(p);
        let first = p % library;
        let second = (p + 1) % library;
        dir.write(
            &format!("{name}/main.nvs"),
            &format!(
                "<?nvs\nautoload 'Framework' from '../lib/Framework';\n\
                 autoload '{name}' from './src';\n\nuse {name}\\Home;\n\n\
                 Home $home = new Home();\necho $home->total(3), \"\\n\";\n"
            ),
        );
        dir.write(
            &format!("{name}/src/Home.nvs"),
            &format!(
                "<?nvs\nnamespace {name};\n\nuse Framework\\Part{first};\n\n\
                 class Home\n{{\n    public function total(int $n): int\n    {{\n        \
                 Part{first} $part = new Part{first}();\n        Helper $helper = new Helper();\n        \
                 return $part->next($n) + $helper->twice($n);\n    }}\n}}\n"
            ),
        );
        dir.write(
            &format!("{name}/src/Helper.nvs"),
            &format!(
                "<?nvs\nnamespace {name};\n\nuse Framework\\Part{second};\n\n\
                 class Helper\n{{\n    public function twice(int $n): int\n    {{\n        \
                 Part{second} $part = new Part{second}();\n        return $part->value($n) * 2;\n    }}\n}}\n"
            ),
        );
    }
    dir
}

/// The workspace index of `dir`, settled, with its build's work taken.
fn index_of(dir: &TempDir) -> (Documents, SymbolIndex) {
    let mut documents = Documents::new();
    documents.survey(CheckScope::Workspace, Some(dir.root()));
    let mut index = SymbolIndex::build(&documents, CheckScope::Workspace, Some(dir.root()));
    index.take_work();
    (documents, index)
}

/// Opens `path` with its text on disk, the way the server takes a
/// `didOpen`, and settles what that queued.
fn open(index: &mut SymbolIndex, documents: &mut Documents, path: &Path) {
    let text = fs::read_to_string(path).expect("a fixture file");
    documents.open(uri_of(path).expect("a temp path is UTF-8"), 1, text);
    documents.resurvey(path);
    index.refresh(documents, path);
    index.settle(documents);
}

/// Applies `edit` to the open document at `path`, the way the server takes a
/// `didChange`, settles every entry the refresh queued, and returns the work
/// all of it did.
fn keystroke(
    index: &mut SymbolIndex,
    documents: &mut Documents,
    path: &Path,
    edit: impl FnOnce(&str) -> String,
) -> Work {
    let uri = uri_of(path).expect("a temp path is UTF-8");
    let document = documents
        .get(&uri)
        .expect("a keystroke is typed in an open document");
    let text = edit(document.text());
    let version = document.version() + 1;
    index.take_work();
    assert!(
        documents.change(&uri, version, text),
        "the document is open"
    );
    documents.resurvey(path);
    index.refresh(documents, path);
    index.settle(documents);
    index.take_work()
}

/// A body-only edit of library class `n`: the number its `value` adds.
fn body_edit(n: usize, to: usize) -> impl FnOnce(&str) -> String {
    move |text: &str| {
        let from = format!("return $n + {n};");
        assert!(text.contains(&from), "the class still has its body");
        text.replacen(&from, &format!("return $n + {n} + {to};"), 1)
    }
}

/// The generator writes what it was asked for, and every file of it checks
/// clean, so a count below is about the work and never about an error.
#[test]
fn the_generated_tree_has_the_programs_and_the_library_it_was_asked_for() {
    let dir = tree(3, 6);
    for n in 0..6 {
        assert!(dir.at(&part(n)).is_file(), "{} was not written", part(n));
    }
    for p in 0..3 {
        for file in ["main.nvs", "src/Home.nvs", "src/Helper.nvs"] {
            let path = dir.at(&format!("{}/{file}", program(p)));
            assert!(path.is_file(), "{} was not written", path.display());
        }
    }
    assert!(!dir.at(&format!("{}/main.nvs", program(3))).exists());
    assert_eq!(program(2), "App3");

    let (documents, index) = index_of(&dir);
    // One program's analysis reaches the whole library through the chain of
    // `next` calls, and reports nothing.
    let main = dir.at("Blog/main.nvs");
    let analysed = nvs_lsp::analyse_file(&documents, &main, 1).expect("the program analyses");
    let errors: Vec<String> = analysed
        .diags
        .iter()
        .filter(|diag| diag.is_error())
        .map(|diag| format!("{diag:?}"))
        .collect();
    assert!(errors.is_empty(), "the program has errors: {errors:#?}");
    assert_eq!(
        analysed.loaded.len(),
        1 + 2 + 6,
        "main, its two files and the library"
    );

    assert_eq!(
        index.len(),
        6 + 3 * 3,
        "the index holds every file of the tree: {:?}",
        index.files().collect::<Vec<_>>()
    );
    assert_eq!(
        index.files_with_errors(),
        0,
        "a generated file has an error"
    );
}

/// A keystroke's work is every analysis it caused. One analysis checks every
/// file of its graph, and parses only the file the keystroke changed.
#[test]
fn a_keystroke_counts_the_files_it_parsed_and_the_bodies_it_checked() {
    let dir = tree(1, 4);
    let (mut documents, mut index) = index_of(&dir);
    let main = dir.at("Blog/main.nvs");
    open(&mut index, &mut documents, &main);

    let work = keystroke(&mut index, &mut documents, &main, |text: &str| {
        text.replacen("total(3)", "total(4)", 1)
    });

    let graph = nvs_lsp::analyse_file(&documents, &main, 2)
        .expect("the program analyses")
        .loaded
        .len();
    assert_eq!(graph, 1 + 2 + 4, "main, its two files and the library");
    assert_eq!(
        work,
        Work {
            parsed: 1,
            checked: graph,
        },
        "a keystroke in a program nothing else reads is one analysis of its graph"
    );
    assert!(
        index.pending().is_empty(),
        "the keystroke settled what it queued"
    );
    assert_eq!(index.work(), Work::default(), "the keystroke took its work");
}

/// A file is parsed again only when its text changed: after the first
/// analysis, a keystroke parses the one file it edited.
#[test]
fn an_unchanged_file_is_parsed_once_across_keystrokes() {
    let dir = tree(2, 40);
    let (mut documents, mut index) = index_of(&dir);
    let home = dir.at("Blog/src/Home.nvs");
    open(&mut index, &mut documents, &home);

    let parsed: Vec<usize> = (1..=3)
        .map(|to| {
            keystroke(&mut index, &mut documents, &home, move |text: &str| {
                text.replacen(
                    "total(int $n): int",
                    &format!("total(int $n): int // {to}"),
                    1,
                )
            })
            .parsed
        })
        .collect();
    assert_eq!(
        parsed,
        [1, 1, 1],
        "each keystroke parses only the file it edited"
    );
}

/// A file nobody has open is parsed again when its text on disk changed, once
/// for every analysis that reads it, and the index then has what the new text
/// declares.
#[test]
fn a_file_whose_text_changed_on_disk_is_parsed_again() {
    let dir = tree(2, 40);
    let (documents, mut index) = index_of(&dir);
    let path = dir.at(&part(5));
    let text = fs::read_to_string(&path).expect("a fixture file");
    let added = text.replacen(
        "    public function next(",
        "    public function fresh(): int\n    {\n        return 5;\n    }\n\n    public function next(",
        1,
    );
    assert_ne!(added, text, "the class still has its `next` method");
    fs::write(&path, added).expect("a writable scratch file");

    index.refresh(&documents, &path);
    index.settle(&documents);
    assert_eq!(
        index.take_work().parsed,
        1,
        "the changed file is parsed once, and no other file is"
    );
    let declared: Vec<String> = index
        .files()
        .filter(|file| file.ends_with("Part5.nvs"))
        .flat_map(|file| index.declarations_in(file))
        .map(|declared| declared.symbol.clone())
        .collect();
    assert!(
        declared
            .iter()
            .any(|symbol| symbol == "Framework\\Part5::fresh"),
        "the index has the method the new text declares: {declared:?}"
    );
}

/// A body-only edit changes nothing another file can see, so the hash stays.
/// So does an edit inside a property hook's body.
#[test]
fn a_body_only_edit_keeps_the_surface_hash() {
    let text = library_class(5, 40);
    let edited = body_edit(5, 1)(&text);
    assert_ne!(edited, text);
    assert_eq!(surface::of_source(&edited), surface::of_source(&text));

    let hooked = "<?nvs\nclass Box\n{\n    public int $size {\n        get => 1;\n    }\n}\n";
    assert_eq!(
        surface::of_source(hooked),
        surface::of_source(&hooked.replace("get => 1;", "get => 2;")),
        "a hook's body is not on the surface"
    );
}

/// An edit another file can see changes the hash: a signature, a constant's
/// value, an attribute, a `require`, a new method and a doc comment.
#[test]
fn a_signature_constant_attribute_or_require_edit_changes_the_surface_hash() {
    let text = format!(
        "{}\nrequire './Other.nvs';\n",
        library_class(0, 40).replacen(
            "    public function value(",
            "    public const int LIMIT = 3;\n\n    public function value(",
            1
        )
    );
    let base = surface::of_source(&text);
    let edits: [(&str, &str, &str); 6] = [
        ("signature", "value(int $n): int", "value(int $n, int $m = 0): int"),
        ("constant value", "LIMIT = 3;", "LIMIT = 4;"),
        ("attribute", "path: '/parts/{id}'", "path: '/part/{id}'"),
        ("require", "'./Other.nvs'", "'./Another.nvs'"),
        (
            "new method",
            "    public function next(",
            "    public function fresh(): int\n    {\n        return 5;\n    }\n\n    public function next(",
        ),
        ("doc comment", "class Part0", "/// A part.\nclass Part0"),
    ];
    for (kind, from, to) in edits {
        assert!(text.contains(from), "the {kind} edit finds its text");
        assert_ne!(
            surface::of_source(&text.replacen(from, to, 1)),
            base,
            "a {kind} edit keeps the surface hash"
        );
    }
}

/// A body-only edit in a library file changes nothing another file can see,
/// so no reader waits.
#[test]
fn a_body_only_keystroke_re_queues_no_reader() {
    let dir = tree(2, 40);
    let (mut documents, mut index) = index_of(&dir);
    let path = dir.at(&part(5));
    open(&mut index, &mut documents, &path);

    let uri = uri_of(&path).expect("a temp path is UTF-8");
    let text = body_edit(5, 1)(documents.get(&uri).expect("open").text());
    assert!(documents.change(&uri, 2, text));
    documents.resurvey(&path);
    index.refresh(&documents, &path);
    assert!(
        index.pending().is_empty(),
        "a body-only edit queued readers: {:?}",
        index.pending()
    );
}

/// An edit to what other files can see of a library file queues every entry
/// that read it.
#[test]
fn a_surface_edit_re_queues_the_entries_that_read_the_file() {
    let dir = tree(2, 40);
    let (mut documents, mut index) = index_of(&dir);
    let path = dir.at(&part(5));
    open(&mut index, &mut documents, &path);

    let uri = uri_of(&path).expect("a temp path is UTF-8");
    let text = documents
        .get(&uri)
        .expect("open")
        .text()
        .replacen("value(int $n): int", "value(int $n, int $m = 0): int", 1);
    assert!(documents.change(&uri, 2, text));
    documents.resurvey(&path);
    index.refresh(&documents, &path);
    let queued: Vec<String> = index
        .pending()
        .iter()
        .map(|entry| entry.to_string_lossy().replace('\\', "/"))
        .collect();
    for program in ["Blog/main.nvs", "Shop/main.nvs"] {
        assert!(
            queued.iter().any(|entry| entry.ends_with(program)),
            "{program} read the file and was not queued: {queued:?}"
        );
    }
}

/// Red until the editor checks only the bodies whose inputs changed: a
/// body-only keystroke in a library file that both programs read parses that
/// file and checks that file's bodies.
#[test]
fn a_body_only_keystroke_in_a_library_file_parses_one_file_and_checks_one_files_bodies() {
    let dir = tree(2, 40);
    let (mut documents, mut index) = index_of(&dir);
    let path = dir.at(&part(5));
    open(&mut index, &mut documents, &path);

    let work = keystroke(&mut index, &mut documents, &path, body_edit(5, 1));
    assert_eq!(
        work,
        Work {
            parsed: 1,
            checked: 1,
        }
    );
}

/// Red until the same: the keystroke's cost does not grow with the programs
/// that read the library.
#[test]
fn a_body_only_keystroke_costs_the_same_with_two_programs_and_with_twenty() {
    let cost = |programs: usize| {
        let dir = tree(programs, 40);
        let (mut documents, mut index) = index_of(&dir);
        let path = dir.at(&part(5));
        open(&mut index, &mut documents, &path);
        keystroke(&mut index, &mut documents, &path, body_edit(5, 1))
    };
    assert_eq!(cost(2), cost(20));
}
